def initialize(context):
    g.index_symbol = '000300.XSHG'
    set_benchmark(g.index_symbol)

    set_option('use_real_price', True)
    set_option('avoid_future_data', True)

    set_order_cost(
        OrderCost(
            open_tax=0,
            close_tax=0.001,
            open_commission=0.0003,
            close_commission=0.0003,
            close_today_commission=0,
            min_commission=5
        ),
        type='stock'
    )

    # 若想让交易回测更接近研究端向量化回测，可把滑点改成 FixedSlippage(0)
    set_slippage(FixedSlippage(0.002))

    g.last_signal_date = None
    g.cash_buffer = 0.005
    g.min_target_weight = 0.0001
    g.max_stock_weight = 0.06

    g.target_weight_by_date, g.target_dates = load_embedded_target_weights()

    log.info('V3 自包含目标权重读取完成，不需要外部 CSV。')
    log.info('调仓期数：{}'.format(len(g.target_dates)))
    if len(g.target_dates) > 0:
        log.info('首期调仓日：{}，末期调仓日：{}'.format(g.target_dates[0], g.target_dates[-1]))

    run_daily(rebalance, time='10:00')


def load_embedded_target_weights():
    raw = ''.join(TARGET_DATA_B64_PARTS)
    csv_bytes = gzip.decompress(base64.b64decode(raw.encode('ascii')))
    csv_text = csv_bytes.decode('utf-8')
    df = pd.read_csv(StringIO(csv_text))

    df['date'] = pd.to_datetime(df['date']).dt.date
    df['code'] = df['code'].astype(str).str.strip()
    df['w'] = pd.to_numeric(df['w'], errors='coerce')
    df = df.dropna(subset=['date', 'code', 'w'])
    df = df[df['w'] > 0]

    df = df.groupby(['date', 'code'], as_index=False)['w'].sum()
    total_w = df.groupby('date')['w'].transform('sum')
    df = df[total_w > 0].copy()
    df['w'] = df['w'] / df.groupby('date')['w'].transform('sum')

    target_weight_by_date = {}
    for dt, sub in df.groupby('date'):
        target_weight_by_date[dt] = dict(zip(sub['code'], sub['w']))

    target_dates = sorted(target_weight_by_date.keys())
    return target_weight_by_date, target_dates


def rebalance(context):
    today = context.current_dt.date()

    if today not in g.target_weight_by_date:
        return

    if g.last_signal_date == today:
        return

    raw_target = g.target_weight_by_date[today]
    if raw_target is None or len(raw_target) == 0:
        log.info('{} 无目标持仓，跳过。'.format(today))
        return

    log.info('=' * 50)
    log.info('开始 V3 调仓：{}'.format(today))
    log.info('原始目标持仓数量：{}'.format(len(raw_target)))

    target = filter_and_normalize_targets(raw_target)

    if len(target) == 0:
        log.info('{} 过滤后无可交易股票，跳过。'.format(today))
        return

    log.info('可交易目标持仓数量：{}'.format(len(target)))
    log.info('目标权重合计：{:.4f}'.format(builtins.sum([float(x) for x in target.values()])))

    current_positions = list(context.portfolio.positions.keys())
    target_stocks = set(target.keys())

    # 先卖出非目标持仓
    for stock in current_positions:
        if stock not in target_stocks:
            if can_sell(stock):
                order_target_value(stock, 0)
                log.info('卖出非目标持仓：{}'.format(stock))
            else:
                log.info('无法卖出，可能停牌或跌停：{}'.format(stock))

    # 再调整目标持仓
    scale = 1.0 - g.cash_buffer

    for stock, weight in target.items():
        if weight < g.min_target_weight:
            continue

        if not can_buy_or_hold(stock):
            log.info('跳过不可买入股票：{}'.format(stock))
            continue

        final_weight = min(weight * scale, g.max_stock_weight)
        order_target_value(stock, context.portfolio.total_value * final_weight)

    g.last_signal_date = today
    log.info('调仓完成：{}'.format(today))


def filter_and_normalize_targets(raw_target):
    """
    过滤不可交易股票，并重新归一化。
    修正版：不再使用 “stock in current_data” 判断。
    聚宽的 get_current_data() 对象有时不支持正常的 in 判断，
    直接用 current_data[stock] 读取更稳。
    """
    current_data = get_current_data()
    target = {}

    reason_count = {
        'invalid_weight': 0,
        'current_data_error': 0,
        'paused': 0,
        'st': 0,
        'limit_up': 0,
        'ok': 0
    }

    for stock, weight in raw_target.items():
        if weight is None:
            reason_count['invalid_weight'] += 1
            continue

        try:
            weight = float(weight)
        except Exception:
            reason_count['invalid_weight'] += 1
            continue

        if np.isnan(weight) or weight <= 0:
            reason_count['invalid_weight'] += 1
            continue

        try:
            cd = current_data[stock]
        except Exception:
            reason_count['current_data_error'] += 1
            continue

        # 停牌不买入
        if getattr(cd, 'paused', False):
            reason_count['paused'] += 1
            continue

        # ST 不买入
        if getattr(cd, 'is_st', False):
            reason_count['st'] += 1
            continue

        # 涨停附近不买入，避免下单失败
        try:
            last_price = getattr(cd, 'last_price', None)
            high_limit = getattr(cd, 'high_limit', None)
            if last_price is not None and high_limit is not None:
                if not np.isnan(last_price) and not np.isnan(high_limit):
                    if last_price >= high_limit * 0.999:
                        reason_count['limit_up'] += 1
                        continue
        except Exception:
            pass

        target[stock] = weight
        reason_count['ok'] += 1

    log.info('过滤统计：{}'.format(reason_count))

    if len(target) == 0:
        return {}

    target = normalize_with_cap(target, g.max_stock_weight)
    return target


def normalize_with_cap(weight_dict, cap):
    """
    将权重归一化，并尽量保证单票权重不超过 cap。
    """
    s = pd.Series(weight_dict, dtype=float)
    s = s.replace([np.inf, -np.inf], np.nan).dropna()
    s = s[s > 0]

    if len(s) == 0:
        return {}

    s = s / s.sum()

    for _ in range(20):
        over = s > cap
        if not over.any():
            break

        excess = (s[over] - cap).sum()
        s[over] = cap

        under = ~over
        if under.sum() == 0 or s[under].sum() <= 0:
            break

        s[under] = s[under] + excess * s[under] / s[under].sum()

    if s.sum() > 0:
        s = s / s.sum()

    return s.to_dict()


def can_sell(stock):
    """
    判断是否可以卖出。
    """
    current_data = get_current_data()

    try:
        cd = current_data[stock]
    except Exception:
        return False

    if getattr(cd, 'paused', False):
        return False

    # 跌停附近不卖，避免无效委托
    try:
        last_price = getattr(cd, 'last_price', None)
        low_limit = getattr(cd, 'low_limit', None)
        if last_price is not None and low_limit is not None:
            if not np.isnan(last_price) and not np.isnan(low_limit):
                if last_price <= low_limit * 1.001:
                    return False
    except Exception:
        pass

    return True


def can_buy_or_hold(stock):
    """
    判断是否可以买入或调整到目标权重。
    """
    current_data = get_current_data()

    try:
        cd = current_data[stock]
    except Exception:
        return False

    if getattr(cd, 'paused', False):
        return False

    if getattr(cd, 'is_st', False):
        return False

    # 涨停附近不买
    try:
        last_price = getattr(cd, 'last_price', None)
        high_limit = getattr(cd, 'high_limit', None)
        if last_price is not None and high_limit is not None:
            if not np.isnan(last_price) and not np.isnan(high_limit):
                if last_price >= high_limit * 0.999:
                    return False
    except Exception:
        pass

    return True


def after_trading_end(context):
    if g.last_signal_date == context.current_dt.date():
        log.info('收盘持仓数量：{}'.format(len(context.portfolio.positions)))
        log.info('组合总资产：{:.2f}'.format(context.portfolio.total_value))
